function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      path.push(...grid[x][y]);
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, steps + 1);
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  return path.sort((a, b) => a - b);
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const queue = [];
  const path = [];

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      queue.push({ row: i, col: j, steps: 0 });
      visited[i][j] = true;
    }
  }

  while (queue.length > 0) {
    const { row, col, steps } = queue.shift();

    if (steps === k) {
      path.push(grid[row][col]);
      return path;
    }

    for (const [dr, dc] of directions) {
