function rgb_to_hsv(r, g, b) {
    // Normalize RGB values to the range [0, 1]
    r /= 255;
    g /= 255;
    b /= 255;

    // Find the maximum and minimum values in RGB
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);

    // Calculate the value (V)
    const v = max;

    // Calculate the saturation (S)
    const s = max === 0 ? 0 : (max - min) / max;

    // Calculate the hue (H)
    let h;
    if (max === min) {
        h = 0;
    } else if (r === max) {
        h = (g - b) / (max - min);
    } else if (g === max) {
        h = 2 + (b - r) / (max - min);
    } else {
        h = 4 + (r - g) / (max - min);
    }

    // Normalize hue to the range [0, 360)
    h = (h + 360) % 360;

    return { h, s, v };
}

function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h;
    let s;
    let v = max;

    if (delta === 0) {
        h = 0;
        s = 0;
    } else {
        s = delta / max;

        let rRatio = (max - r) / delta;
        let gRatio = (max - g) / delta;
        let bRatio = (max - b) / delta;

        if (r === max) {
            h = (g - b) / delta;
        } else if (g === max) {
            h = 2 + (b - r) / delta;
        } else {
            h = 4 + (r - g) / delta;
        }

        h /= 6;
        if (h < 0) h += 1;
    }

    return [h * 360, s * 100, v * 100];
}

