function max_sum(arr){
  const n = arr.length;
  const dp = new Array(n).fill(0);
  const dp_desc = new Array(n).fill(0);

  // Find the maximum sum of a bitonic subsequence increasing
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && dp[j] + arr[i] > dp[i]) {
        dp[i] = dp[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of a bitonic subsequence decreasing
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j] && dp_desc[j] + arr[i] > dp_desc[i]) {
        dp_desc[i] = dp_desc[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of the bitonic subsequence
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    max_sum = Math.max(max_sum, dp[i] + dp_desc[i] - arr[i]);
  }

  return max_sum;
}

function max_sum(arr) {
    const n = arr.length;
    const dp = Array.from({ length: n }, () => Array(n).fill(0));

    // Calculate the maximum sum of increasing subsequences
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j] && dp[i][j] < arr[i] + dp[j][i]) {
                dp[i][j] = arr[i] + dp[j][i];
            }
        }
    }

    // Calculate the maximum sum of decreasing subsequences
    const dpRev = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j >= i; j--) {
            if (arr[i] > arr[j] && dpRev[i][j] < arr[i] + dpRev[j][i]) {
                dpRev[i][j] = arr[i] + dpRev[j][i];
            }
        }
    }

    // Find the maximum sum of a bitonic subsequence
    let maxSum = 0;
    for (let i = 0; i < n; i++) {
        for (let j = i; j < n; j++) {
            if (arr[i] < arr[j] && dp[i][j] + dpRev[j][i] > maxSum) {
                maxSum = dp[i][j] + dpRev[j][i];
            }
        }
    }

