    // If the current digit is less than the digit immediately after it
    if (digits[i] < digits[i + 1]) {
      // Find the smallest digit to the right of the current digit that is greater than it
      let j = digits.length - 1;
      while (digits[j] <= digits[i]) {
        j--;
      }
      // Swap the current digit with the smallest digit found
      [digits[i], digits[j]] = [digits[j], digits[i]];
      // Sort the digits to the right of the current digit
      digits.splice(i + 1);
      digits.sort((a, b) => a - b);
