      if (arr[i] > arr[j] && dpDesc[j] + arr[i] > dpDesc[i]) {
        dpDesc[i] = dpDesc[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let maxSum = 0;
  for (let i = 0; i < n; i++) {
