  let adverbs = ["quickly", "slowly", "happily", "sadly", "angrily", "excitedly", "gratefully", "seriously", "wonderfully"];
  let positions = [];
  let adverbIndex = 0;

  while (adverbIndex < adverbs.length) {
    const regex = new RegExp("\\b" + adverbs[adverbIndex] + "\\b", "g");
    const matches = text.match(regex);
    if (matches) {
      for (let i = 0; i < matches.length; i++) {
        positions.push({ word: matches[i], position: i });
      }
    }
    adverbIndex++;
  }

  return positions;
}

